<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {api,put} from '../../services/api'
import {Save,RefreshCw,Search,FilePenLine,CheckCircle2,AlertCircle,ArrowUpRight} from '../../components/admin/AndarmaFaIcons.js'
const values=ref({}),original=ref({}),error=ref(''),success=ref(''),loading=ref(false),saving=ref(false),query=ref(''),active=ref('all')
const sectionNames={'inicio':'Inicio','nosotros':'Acerca de ANDARMA','opciones':'Viviendas y terrenos','por-que-andarma':'Por qué ANDARMA','como-comprar':'Cómo comprar','testimonios':'Testimonios','contacto':'Contacto'}
const sections=computed(()=>[...new Set(Object.keys(values.value).map(k=>k.split('.')[0]))])
const grouped=computed(()=>Object.entries(values.value).filter(([k])=>(active.value==='all'||k.split('.')[0]===active.value)&&(k.toLowerCase().includes(query.value.toLowerCase())||String(sectionNames[k.split('.')[0]]||'').toLowerCase().includes(query.value.toLowerCase()))).reduce((acc,[key])=>{const section=key.split('.')[0];(acc[section] ||= []).push(key);return acc},{}))
const changed=computed(()=>Object.keys(values.value).filter(key=>values.value[key]!==original.value[key]))
function niceKey(k){const parts=k.split('.');const type=parts[1]==='h2'?'Título principal':parts[1]==='h3'?'Subtítulo':'Texto';return `${type} ${parts.at(-1)} · ${k}`} 
async function load(){loading.value=true;error.value='';try{const r=await api('/admin/site-content');values.value={...r.data};original.value={...r.data}}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(){if(saving.value||!changed.value.length)return;saving.value=true;error.value='';success.value='';try{if(changed.value.some(k=>!String(values.value[k]??'').trim())){error.value='Los campos no pueden quedar vacíos. Revisa los textos marcados.';return}const r=await put('/admin/site-content',{data:Object.fromEntries(changed.value.map(k=>[k,values.value[k]]))});values.value={...r.data};original.value={...r.data};success.value='Contenido guardado en Laravel. Abre «Ver página» y actualiza la pestaña para comprobarlo.'}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="admin-page-head"><div><span class="admin-kicker">SITIO Y CONTENIDO / EDITOR</span><h1>Contenido web<span class="heading-dot">.</span></h1><p>Actualiza los textos del sitio sin modificar el código o las animaciones.</p></div><a class="admin-outline" href="/" target="_blank" rel="noopener"><ArrowUpRight :size="17"/> Ver página</a></div>
<div v-if="error" role="alert" class="admin-alert error"><AlertCircle :size="17"/>{{error}}</div><div v-if="success" role="status" class="admin-alert success"><CheckCircle2 :size="17"/>{{success}}</div>
<div class="ad-form-guidance"><span>Este editor modifica exclusivamente los textos conectados al CMS. No altera la maquetación, las fotografías ni las animaciones de la página pública. Si un texto no cambia en el sitio, revisa que tenga el atributo <code>data-andarma-content</code> correspondiente.</span></div><div class="content-admin-layout"><aside class="content-admin-side"><div class="content-admin-side-title">SECCIONES DEL SITIO</div><button :class="{active:active==='all'}" @click="active='all'">Todas las secciones <span>{{Object.keys(values).length}}</span></button><button v-for="section in sections" :key="section" :class="{active:active===section}" @click="active=section">{{sectionNames[section]||section}} <span>{{Object.keys(values).filter(k=>k.startsWith(section+'.')).length}}</span></button><div class="content-admin-help"><FilePenLine :size="22"/><strong>Edición de contenido</strong><p>Solo se guardan los campos que hayas modificado.</p></div></aside><section class="content-admin-main"><div class="content-admin-toolbar"><label class="admin-search"><Search :size="17"/><input v-model="query" placeholder="Buscar texto o sección…" aria-label="Buscar contenido"/></label><button class="admin-outline" :disabled="loading" @click="load"><RefreshCw :size="17"/> Recargar</button></div><div v-if="loading" class="admin-panel content-admin-empty">Cargando contenido…</div><template v-else><article v-for="(keys,section) in grouped" :key="section" class="admin-panel content-admin-card"><header><div><span class="admin-kicker">SECCIÓN WEB</span><h2>{{sectionNames[section]||section}}</h2></div><span class="admin-count-tag">{{keys.length}} campos</span></header><div class="content-admin-fields"><label v-for="key in keys" :key="key" class="admin-field"><span>{{niceKey(key)}} <small v-if="values[key]!==original[key]" class="content-edited">● Modificado</small></span><textarea v-model="values[key]" rows="3" maxlength="1500" :class="{'ad-changed-input':values[key]!==original[key]}" :aria-label="niceKey(key)"/><small class="content-char-count">{{(values[key]||'').length}} / 1500</small></label></div></article><div v-if="!Object.keys(grouped).length" class="admin-panel content-admin-empty">No hay contenido que coincida con la búsqueda.</div></template></section></div>
<div class="content-admin-savebar"><div><strong>{{changed.length ? `${changed.length} cambio${changed.length===1?'':'s'} sin guardar`:'Contenido al día'}}</strong><small>{{changed.length?'Guarda para publicar las modificaciones.':'No hay modificaciones pendientes.'}}</small></div><button class="admin-primary" :disabled="saving||loading||!changed.length" @click="save"><Save :size="17"/>{{saving?'Guardando…':'Guardar cambios'}}</button></div>
</template>
